def A(i, who, f, what, anim, micro, reactions, consequences, sfx, persists=None, sign=None, recipe=None):
    a = {"id": i, "who": who, "f": f, "what": what, "anim": anim, "micro": micro, "reactions": reactions, "consequences": consequences, "sfx": sfx}
    if persists: a["persists"] = persists
    if sign: a["sign"] = sign
    if recipe: a["recipe"] = recipe
    return a
